// Input: $json.touchpoints array from client JSON
// Output: filtered list of touchpoints due within LOOKBACK_DAYS (3) to LOOKAHEAD_DAYS (0)
const LOOKBACK_DAYS = 3;
const LOOKAHEAD_DAYS = 0;

const today = new Date($input.first().json.today_date);
const client = $input.first().json.client_name;
const touchpoints = $input.first().json.touchpoints || [];

// Filter touchpoints that are due
const dueTouchpoints = touchpoints.filter(tp => {
    if (!tp.due_date || tp.due_date === '') return false;

    const dueDate = new Date(tp.due_date);
    const daysDiff = Math.round((dueDate - today) / (1000 * 60 * 60 * 24));

    // Within range: -LOOKBACK_DAYS to +LOOKAHEAD_DAYS
    return daysDiff >= -LOOKBACK_DAYS && daysDiff <= LOOKAHEAD_DAYS;
});

// Return enriched data
return dueTouchpoints.map(tp => ({
    json: {
        client,
        touchpoint_id: tp.id,
        touchpoint_label: tp.label,
        due_date: tp.due_date,
        template_name: tp.template,
        client_name: tp.client_name,
        client_email: tp.client_email
    }
}));

// Format email draft from template
const template = $input.first().json.content;
const client = $input.first().json.client_name;
const touchpointId = $input.first().json.touchpoint_id;
const touchpointLabel = $input.first().json.touchpoint_label;

try {
    // Extract template section (assuming markdown with headers)
    const lines = template.split('\n');
    let inSection = false;
    let draftLines = [];

    // Find template section for this touchpoint
    for (const line of lines) {
        if (line.includes(`## ${touchpointId}:`) || line.includes(`## ${touchpointLabel}`)) {
            inSection = true;
            continue;
        }

        if (inSection && line.startsWith('## ')) {
            break; // Next section
        }

        if (inSection) {
            draftLines.push(line);
        }
    }

    const draftContent = draftLines.join('\n').trim();

    // Create subject line
    const subject = `[D2M] ${client} — ${touchpointLabel}`;

    return [{
        json: {
            client,
            touchpoint_id: touchpointId,
            draft_subject: subject,
            draft_body: draftContent,
            recipient_email: $input.first().json.client_email,
            completed: draftContent.length > 0
        }
    }];
} catch (error) {
    return [{
        json: {
            error: error.message,
            client,
            touchpoint_id: touchpointId,
            completed: false
        }
    }];
}
